declare(strict_types=1);$root=dirname(__DIR__);$read=static fn(string $p):string=>(string)file_get_contents($root.'/'.$p);$assert=static function(bool $v,string $m):void{if(!$v)throw new RuntimeException($m);};$view=$read('app/Views/public/portal.php');foreach(['ThemeService::allowed','public-nav','public-hero','public-grid','public-list','table-wrap','--champ-primary']as$n)$assert(str_contains($view,$n),'Missing portal '.$n);$css=$read('public/assets/css/public-portal.css');foreach(['.public-nav','.public-hero','.public-grid','.public-list','@media(max-width:800px)','@media(max-width:520px)']as$n)$assert(str_contains($css,$n),'Missing responsive public UI '.$n);echo "PUBLIC_UI_E2E_OK\n";
